if (cmdLine.handleFlag("options", false)) {
  getOrOpen3PaneWindow().then(win => win.openPreferencesTab());
  cmdLine.preventDefault = true;
}

if (cmdLine.handleFlag("calendar", false)) {
  getOrOpen3PaneWindow().then(win => win.toCalendar());
  cmdLine.preventDefault = true;
}

if (cmdLine.findFlag("compose", false) != -1) {
  // E.g. -compose "to=john@example.com,subject='Dinner tonight?'"
  let param = "";
  try {
    param = cmdLine.handleFlagWithParam("compose", false);
    // NS_ERROR_INVALID_ARG is thrown when flag exists, but has no param.
  } catch (e) {
    if (e.result != Cr.NS_ERROR_INVALID_ARG) {
      throw Components.Exception(
        "Error processing -compose command.",
        e.result
      );
    }
    cmdLine.handleFlag("compose", false);
  }
  const arg = Cc["@mozilla.org/supports-string;1"].createInstance(
    Ci.nsISupportsString
  );
  arg.data = param;
  const args = Cc["@mozilla.org/array;1"].createInstance(
    Ci.nsIMutableArray
  );
  args.appendElement(arg);
  args.appendElement(cmdLine);

  // First ensure main window is opened earlier than compose window, to
  // ensure proper initialization.
  getOrOpen3PaneWindow().then(win => {
    if (!MailServices.accounts.defaultAccount) {
      // No account yet; can't compose.
      return;
    }
    Services.ww.openWindow(
      win,
      "chrome://messenger/content/messengercompose/messengercompose.xhtml",
      "_blank",
      "chrome,dialog=no,all",
      args
    );
  });
  cmdLine.preventDefault = true;
}

if (cmdLine.handleFlag("keymanager", false)) {
  getOrOpen3PaneWindow().then(win => win.openKeyManager());
  cmdLine.preventDefault = true;
}

if (cmdLine.handleFlag("setDefaultMail", false)) {
  var shell = Cc["@mozilla.org/mail/shell-service;1"].getService(
    Ci.nsIShellService
  );
  shell.setDefaultClient(true, Ci.nsIShellService.MAIL);
}

